import {defaultPersonal,PersonalError,PERSONAL_LIMITS,createPersonalDeck,renamePersonalDeck,upsertPersonalWord,removePersonalWord,restorePersonalWord,filteredPersonalWords,createPersonalSession,getPersonalQuestion,savePersonalForReview,preparePersonalImport,applyPersonalImport,personalCSV} from './personal-data.js';
import {recordAnswer} from './model.js';
import {answerCard} from './practice-ui.js';
import {kanjiText} from './reading-ui.js';
import {pronunciationControls} from './word-speech.js';

export function createPersonalFeature({getState,commit,ui,toast,isBusy=()=>false,onQuestionStart=()=>{},render}){
 let editorOpen=false,editingId=null,wordDraft=null,deckEditingId=null,deckDraft='',error=null,preview=null,csvText='',previewText='',importDeckId='all',importing=false,readingCSV=false,fileGeneration=0,startedAt=performance.now();
 const current=()=>({...defaultPersonal(),...getState().personal});
 const repaint=async()=>{if(render)render();else await commit(structuredClone(getState()));};
 const wordsWithState=()=>filteredPersonalWords({...getState(),personal:current()});
 const explain=issue=>{
  const {T}=ui(),messages={required:T('Gerekli alanı doldur.','Fill in the required field.'),'too-long':T('Bu alan izin verilen uzunluğu aşıyor.','This field exceeds its length limit.'),'control-character':T('Bu alanda desteklenmeyen kontrol karakterleri var.','This field contains unsupported control characters.'),'kana-required':T('Okunuşu hiragana/katakana ile yaz; kanji veya romaji kullanma.','Write the reading in hiragana/katakana, without kanji or romaji.'),'too-many-tags':T('En fazla 12 etiket ekleyebilirsin.','You can add up to 12 tags.'),'invalid-level':T('Geçerli bir düzey seç.','Choose a valid level.'),'missing-deck':T('Önce geçerli bir deste oluştur veya seç.','Create or select a valid deck first.'),'duplicate-deck':T('Bu adla bir deste zaten var.','A deck with this name already exists.'),'duplicate-word':T('Bu destede aynı yazım ve okunuş zaten var.','This deck already has that spelling and reading.'),'missing-word':T('Bu kelime artık bulunamıyor.','This word is no longer available.'),'deck-limit':T(`En fazla ${PERSONAL_LIMITS.decks} deste saklanabilir.`,`Up to ${PERSONAL_LIMITS.decks} decks can be stored.`),'word-limit':T(`Kaldırılanlar dahil en fazla ${PERSONAL_LIMITS.words} kişisel kelime saklanabilir.`,`Up to ${PERSONAL_LIMITS.words} personal words, including removed words, can be stored.`),'csv-size':T('CSV dosyası en fazla 1 MB olabilir.','The CSV file must be no larger than 1 MB.'),'csv-row-limit':T('Bir seferde en fazla 1000 satır içe aktarılabilir.','You can import up to 1000 rows at once.'),'csv-field-limit':T('CSV alanlarından biri çok uzun.','A CSV field is too long.'),'csv-quotes':T('CSV tırnakları kapanmıyor veya yanlış yerde.','CSV quotes are unclosed or misplaced.'),'csv-empty':T('CSV içinde kelime satırı bulunamadı.','No word rows were found in the CSV.'),'csv-header':T('Başlıklar written, reading, tr içermeli; isteğe bağlı en, deck, tags, notes, example, level sütunları kullanılabilir. Yinelenen veya tanınmayan başlık olmasın.','Headers must include written, reading and tr; optional columns are en, deck, tags, notes, example and level. Avoid duplicate or unknown headers.'),'csv-columns':T('Satırın sütun sayısı başlıkla eşleşmiyor.','The row has a different number of columns than the header.'),'csv-changed':T('CSV metni değişti. Onaylamadan önce yeniden önizle.','The CSV text changed. Preview it again before confirming.'),'csv-invalid':T('CSV eklenemedi. Önizlemeyi ve alanları kontrol et.','The CSV could not be added. Check the preview and fields.')};
  const fields={written:T('Japonca kelime','Japanese word'),reading:T('Kana okunuşu','Kana reading'),tr:T('Türkçe anlam','Turkish meaning'),en:T('İngilizce anlam','English meaning'),deck:T('Deste','Deck'),tags:T('Etiketler','Tags'),notes:T('Notlar','Notes'),example:T('Örnek','Example'),level:T('Düzey','Level')};
  return `${fields[issue?.field]?fields[issue.field]+': ':''}${messages[issue?.code]||T('İşlem tamamlanamadı. Alanları kontrol et.','The action could not be completed. Check the fields.')}`;
 };
 const errorHTML=()=>error?`<p class="personal-error" role="alert">${ui().esc(explain(error))}</p>`:'';
 const deckOptions=(p,value,all=true)=>`${all?`<option value="all" ${value==='all'?'selected':''}>${ui().T('Bütün desteler','All decks')}</option>`:''}${p.decks.map(deck=>`<option value="${ui().esc(deck.id)}" ${value===deck.id?'selected':''}>${ui().esc(deck.name)}</option>`).join('')}`;
 const download=(text,name)=>{const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
 function wordForm(p){
  if(!editorOpen||!p.decks.length)return '';
  const {T,esc}=ui(),old=p.words.find(word=>word.id===editingId),value=wordDraft||old||{},deckId=value.deckId||(p.selectedDeckId!=='all'?p.selectedDeckId:p.decks[0].id),meaning=value.meaning||{tr:value.tr||'',en:value.en||''};
  return `<section class="personal-panel personal-editor" aria-labelledby="personal-editor-title">
   <div class="personal-editor-heading"><div><p class="eyebrow">${T('KENDİ KELİME KARTIN','YOUR WORD CARD')}</p><h2 id="personal-editor-title">${old?T('Kelimeyi düzenle','Edit word'):T('Yeni kelime','New word')}</h2></div><button type="button" class="personal-editor-close" data-action="personal-cancel-editor" aria-label="${T('Kelime formunu kapat','Close word editor')}">×</button></div>
   <p class="personal-small">${T('Japonca kelime, kana okunuşu ve Türkçe anlam zorunludur. Bu kayıt senin notundur; okunuş veya anlam otomatik doğrulanmaz.','Japanese word, kana reading and Turkish meaning are required. This is your own note; readings and meanings are not automatically verified.')}</p>
   <form data-form="personal-word">${old?`<input type="hidden" name="id" value="${esc(old.id)}">`:''}
    <fieldset class="personal-fieldset"><legend>${T('Kelime bilgisi','Word details')}</legend><div class="personal-form-grid">
     <label>${T('Japonca kelime','Japanese word')}<input name="written" required maxlength="80" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(value.written||'')}" placeholder="学校"></label>
     <div class="personal-field"><label for="personal-kana-reading">${T('Kana okunuşu','Kana reading')}</label><input id="personal-kana-reading" name="reading" required maxlength="150" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" aria-describedby="personal-kana-help" value="${esc(value.reading||'')}" placeholder="がっこう"><p id="personal-kana-help" class="personal-field-help">${T('Hiragana veya katakana kullan: がっこう gibi.','Use hiragana or katakana, such as がっこう.')}</p></div>
     <label>${T('Türkçe anlam','Turkish meaning')}<input name="tr" required maxlength="200" value="${esc(meaning.tr)}" placeholder="okul"></label>
     <label>${T('İngilizce anlam · isteğe bağlı','English meaning · optional')}<input name="en" maxlength="200" value="${esc(meaning.en)}" placeholder="school"></label>
    </div></fieldset>
    <fieldset class="personal-fieldset"><legend>${T('Deste ve etiketler','Deck and tags')}</legend><div class="personal-form-grid">
     <label>${T('Deste','Deck')}<select name="deckId" required>${deckOptions(p,deckId,false)}</select></label>
     <label>${T('Düzey etiketi','Level label')}<select name="level"><option value="unassigned">${T('Belirtilmedi','Unspecified')}</option>${['N5','N4','N3','N2','N1'].map(level=>`<option ${value.level===level?'selected':''}>${level}</option>`).join('')}</select></label>
    </div><label class="personal-tags-field">${T('Etiketler · virgülle ayır','Tags · separate with commas')}<input name="tags" maxlength="500" value="${esc(Array.isArray(value.tags)?value.tags.join(', '):value.tags||'')}" placeholder="Genki 1, Bölüm 3, Yazılım"></label><p class="personal-field-help">${T('En fazla 12 etiket. Düzey, senin çalışma etiketindir; resmî JLPT sınıflandırması değildir.','Up to 12 tags. The level is your study label, not an official JLPT classification.')}</p></fieldset>
    <details class="personal-optional-notes" data-disclosure-key="personal-word-notes-${esc(old?.id||'new')}" ${value.example||value.notes?'open':''}><summary>${T('Örnek cümle ve not ekle','Add an example and a note')}<span class="personal-optional-label">${T('isteğe bağlı','optional')}</span></summary>
     <label>${T('Örnek cümle · isteğe bağlı','Example sentence · optional')}<textarea name="example" rows="2" maxlength="300" lang="ja" placeholder="学校へ行きます。">${esc(value.example||'')}</textarea></label>
     <label>${T('Kendi notun · isteğe bağlı','Your note · optional')}<textarea name="notes" rows="2" maxlength="1000">${esc(value.notes||'')}</textarea></label>
    </details>
    <div class="personal-editor-footer">${old?`<p class="personal-small">${T('Kelime veya anlam değişirse mevcut tekrar kartları yeniden vadesi gelmiş olur. Eski cevapların korunur.','Changing the word or meaning makes existing review cards due again. Your previous answers are preserved.')}</p>`:''}<div class="personal-actions"><button class="btn primary" type="submit">${T('Kelimeyi kaydet','Save word')}</button><button class="btn secondary" type="button" data-action="personal-cancel-editor">${T('Vazgeç','Cancel')}</button></div></div>
   </form></section>`;
 }
 function importArea(p){
  const {T,esc}=ui();return `<details class="personal-panel personal-import" data-disclosure-key="personal-import">
   <summary><span>${T('CSV ile toplu ekle','Import words from CSV')}</span><span class="personal-summary-meta" aria-hidden="true">1 MB · 1000 ${T('satır','rows')}</span><span class="personal-chevron" aria-hidden="true">⌄</span></summary>
   <div class="personal-import-body"><p class="personal-small">${T('Dosyanı seç veya metni yapıştır. Önce önizle, ardından eklemeyi onayla. Dosya bu tarayıcıda okunur; sunucuya yüklenmez.','Choose a file or paste text. Preview it, then confirm adding the words. The file is read in this browser and is not uploaded.')}</p>
   <button type="button" class="subtle-link personal-template-link" data-action="personal-csv-template">${T('Örnek CSV indir','Download sample CSV')} <span aria-hidden="true">↓</span></button>
   <form data-form="personal-import-preview">${readingCSV?`<p class="personal-small" role="status">${T('Dosya okunuyor…','Reading file…')}</p>`:''}
    <label class="personal-file-choice">${T('CSV dosyası seç','Choose a CSV file')}<input type="file" accept=".csv,text/csv" data-personal-file="csv"></label>
    <details class="personal-csv-paste" data-disclosure-key="personal-csv-text" ${csvText?'open':''}><summary>${T('CSV metnini yapıştır / düzenle','Paste or edit CSV text')}</summary><label>${T('CSV metni','CSV text')}<textarea name="csvText" data-personal-csv="text" rows="5" maxlength="1000000" placeholder="written,reading,tr,en,deck,tags" ${readingCSV?'disabled':''}>${esc(csvText)}</textarea></label></details>
    <label>${T('Varsayılan deste','Default deck')}<select name="importDeckId">${deckOptions(p,importDeckId,true)}</select></label><p class="personal-field-help">${T('CSV satırında deste adı yoksa bu seçim kullanılır. Bütün desteler seçiliyken bu satırlar “İçe aktarılanlar” destesine gider.','This selection is used when a CSV row has no deck name. With All decks selected, those rows go to “İçe aktarılanlar”.')}</p>
    <details class="personal-csv-help" data-disclosure-key="personal-csv-help"><summary>${T('CSV biçimi ve ipuçları','CSV format and tips')}</summary><p class="personal-small">${T('Gerekli sütunlar: written, reading, tr. Virgül veya noktalı virgül ayırıcı kullan; tags alanında etiketleri | ile ayırabilirsin. En fazla 1 MB ve 1000 satır eklenebilir. Hatalı satır varsa hiçbir kelime eklenmez.','Required columns: written, reading, tr. Use a comma or semicolon delimiter; separate tags with |. The limit is 1 MB and 1000 rows. If a row is invalid, no words are added.')}</p><p class="personal-small">${T('CSV dışa aktarımında formül başlangıcı olan alanlara tek tırnak öneki eklenir. Yeniden içe almadan önce önizlemeyi kontrol et.','CSV export prefixes spreadsheet formula starts with an apostrophe. Check the preview before importing the file again.')}</p></details>
    <button class="btn secondary personal-preview-button" type="submit" ${readingCSV?'disabled':''}>${T('Önizle','Preview')}</button>
   </form>${preview?`<section class="personal-preview" aria-label="${T('CSV önizlemesi','CSV preview')}"><div class="personal-preview-heading"><h3>${T('Eklenmeden önce kontrol et','Check before adding')}</h3><span class="personal-summary-meta">${preview.count} ${T('geçerli satır',preview.count===1?'valid row':'valid rows')} · ${preview.errors.length} ${T('hata',preview.errors.length===1?'error':'errors')}</span></div>${preview.errors.length?`<ul class="personal-error">${preview.errors.slice(0,20).map(issue=>`<li>${issue.row?`${T('Satır','Row')} ${issue.row}: `:''}${esc(explain(issue))}</li>`).join('')}</ul>${preview.errors.length>20?`<p class="personal-small">${T('İlk 20 hata gösteriliyor.','Showing the first 20 errors.')}</p>`:''}`:''}${preview.rows.length?`<div class="personal-preview-scroll" data-scroll-key="personal-csv-preview"><table><caption class="sr-only">${T('İçe aktarılacak kelimeler','Words to import')}</caption><thead><tr><th scope="col">${T('Kelime','Word')}</th><th scope="col">${T('Okunuş','Reading')}</th><th scope="col">${T('Anlam','Meaning')}</th><th scope="col">${T('Deste','Deck')}</th></tr></thead><tbody>${preview.rows.slice(0,20).map(row=>`<tr><td lang="ja">${esc(row.written)}</td><td lang="ja">${esc(row.reading)}</td><td>${esc(row.meaning.tr)}</td><td>${esc(row.deckName)}</td></tr>`).join('')}</tbody></table></div>${preview.rows.length>20?`<p class="personal-small">${T('Önizlemede ilk 20 satır gösterilir; onay tüm geçerli satırları ekler.','The preview shows the first 20 rows; confirmation adds all validated rows.')}</p>`:''}`:''}<div class="personal-actions"><button class="btn primary" type="button" data-action="personal-import-confirm" ${preview.errors.length||!preview.rows.length||importing?'disabled':''}>${T(`${preview.count} kelimeyi eklemeyi onayla`,`Confirm adding ${preview.count} ${preview.count===1?'word':'words'}`)}</button><button class="btn secondary" type="button" data-action="personal-import-cancel">${T('Önizlemeyi kapat','Close preview')}</button></div></section>`:''}</div></details>`;
 }
 function sessionArea(state,p){
  const {T,esc}=ui(),s=p.session;if(!s)return '';
  if(s.phase==='done'){const events=state.events.filter(event=>s.eventIds.includes(event.id));return `<section class="personal-panel personal-session"><h2 tabindex="-1">${T('Kişisel tur tamamlandı.','Personal round complete.')}</h2><p>${events.filter(event=>event.correct).length} / ${events.length} ${T('doğru cevap. Cevapların tekrar planında.',events.length===1?'correct answer. Your answer is in the review schedule.':'correct answers. Your answers are in the review schedule.')}</p><button class="btn primary" data-action="personal-close-session">${T('Destelerime dön','Back to my decks')}</button></section>`;}
  const q=s.questions?.[s.index]||getPersonalQuestion(s.ids[s.index],state),event=state.events.find(e=>e.id===s.feedback);
  if(!q)return `<section class="personal-panel"><p>${T('Bu soru artık kullanılamıyor. Destelerine dönerek yeni tur başlat.','This question is no longer available. Return to your decks and start a new round.')}</p><button class="btn secondary" data-action="personal-close-session">${T('Destelerime dön','Back to my decks')}</button></section>`;
  let exercise=answerCard(q,event,ui(),{form:'personal-answer',next:'personal-next',practiceClass:'personal-question'});
  exercise=exercise.replace('<form data-form="personal-answer"',`<form data-form="personal-answer" data-question-id="${esc(q.id)}" data-session-id="${esc(s.id)}"`);
  return `<section class="personal-session"><div class="section-top"><h2 tabindex="-1">${T('Kendi kelimelerim','My words')} · ${s.index+1} / ${s.ids.length}</h2><button class="subtle-link" data-action="personal-close-session">${T('Kartlara dön','Back to cards')}</button></div><p class="personal-small">${T('Bu tur başlangıçtaki seçkiyi ve cevap anahtarlarını kullanır. Kendi içeriğin; editör onayı yok.','This round uses the starting selection and answer keys. Your own content; not editor reviewed.')}</p>${exercise}</section>`;
 }
 function page(){
  const state=getState(),p=current(),{T,L,esc}=ui(),words=wordsWithState(),selected=words.find(word=>word.id===p.selectedWordId)||words[0],removed=p.words.filter(word=>word.deletedAt),selectedDeck=p.decks.find(deck=>deck.id===p.selectedDeckId);
  const header=`<div class="page-heading"><p class="eyebrow">${T('KENDİ NOTLARINDAN ÇALIŞ','STUDY YOUR OWN NOTES')}</p><h1 tabindex="-1">${T('Kişisel kelime destelerin.','Your vocabulary decks.')}</h1><p class="muted">${T('Genki bölümlerini, işte gördüğün terimleri veya animede duyduğun kelimeleri kendi destelerinde topla.','Collect Genki chapters, work terms or words from anime in your own decks.')}</p></div><p class="personal-disclosure">${T('Kayıtlar cihazda tutulur; Tercihler ve veriler bölümünde eşitlemeyi açabilirsin. Kendi kelimelerin otomatik çevrilmez veya kaynak doğrulamasından geçmiş sayılmaz.','Records stay on this device; you can enable cloud sync in Preferences & data. Your words are not automatically translated or treated as source-verified.')}</p>${errorHTML()}`;
  if(p.session)return header+sessionArea(state,p);
  const options=`<section class="personal-panel personal-collection" aria-labelledby="personal-collection-title"><div class="personal-collection-heading"><h2 id="personal-collection-title">${T('Destelerim','My decks')}</h2><span class="personal-summary-meta">${p.decks.length} ${T('deste',p.decks.length===1?'deck':'decks')} · ${p.words.filter(word=>!word.deletedAt).length} ${T('kelime',p.words.filter(word=>!word.deletedAt).length===1?'word':'words')}</span></div>
   <div class="personal-filter-row"><label>${T('Deste','Deck')}<select data-personal="deck">${deckOptions(p,p.selectedDeckId)}</select></label><form data-form="personal-search"><label>${T('Kelime veya etikette ara','Search words or tags')}<input type="search" name="query" maxlength="100" value="${esc(p.search)}" placeholder="Genki 1, Bölüm 3…"></label><button class="btn secondary" type="submit">${T('Ara','Search')}</button></form></div>
   <div class="personal-actions"><button class="btn primary" data-action="personal-new-word" ${!p.decks.length?'disabled':''}>+ ${T('Kelime ekle','Add word')}</button>${selectedDeck?`<button class="btn secondary" data-action="personal-rename-deck" data-deck-id="${esc(selectedDeck.id)}">${T('Deste adını değiştir','Rename deck')}</button>`:''}<button class="btn secondary" data-action="personal-export" ${!words.length?'disabled':''}>CSV ${T('dışa aktar','export')}</button></div>
   <details class="personal-deck-editor" data-disclosure-key="${deckEditingId?'personal-rename-'+esc(deckEditingId):'personal-new-deck'}" ${deckEditingId||!p.decks.length?'open':''}><summary>${deckEditingId?T('Deste adını düzenle','Edit deck name'):T('Yeni deste oluştur','Create a new deck')}</summary><form class="personal-deck-form" data-form="personal-deck">${deckEditingId?`<input type="hidden" name="id" value="${esc(deckEditingId)}">`:''}<label>${deckEditingId?T('Yeni deste adı','New deck name'):T('Yeni deste oluştur','Create a deck')}<input name="name" required maxlength="80" value="${esc(deckDraft)}" placeholder="Genki 1 · Bölüm 3"></label><button class="btn secondary" type="submit">${deckEditingId?T('Adı kaydet','Save name'):T('Deste oluştur','Create deck')}</button>${deckEditingId?`<button type="button" class="subtle-link" data-action="personal-cancel-deck">${T('Vazgeç','Cancel')}</button>`:''}</form><p class="personal-field-help">${T('Kitap bölümü, konu veya kendi çalışma başlığınla adlandırabilirsin.','Use a book chapter, topic or a study title of your own.')}</p></details></section>`;
  const study=`<div class="personal-practice-controls"><label>${T('Alıştırma türü','Exercise type')}<select data-personal="mode">${[['meaning',T('Anlamını yaz','Type the meaning')],['reading',T('Okunuşunu yaz','Type the reading')],['writing',T('Japonca yaz','Write in Japanese')]].map(([mode,label])=>`<option value="${mode}" ${p.mode===mode?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn primary" data-action="personal-start" ${!words.length?'disabled':''}>${T('Bu seçkiyle pratik yap','Practice this selection')}</button><span class="personal-small">${Math.min(words.length,10)} ${T('soru · karışık tur',Math.min(words.length,10)===1?'question · shuffled round':'questions · shuffled round')}</span></div>`;
  const browse=selected?`<div class="personal-browser"><aside class="personal-word-list" data-scroll-key="personal-word-list" aria-label="${T('Kişisel kelimeler','Personal words')}"><p class="personal-list-count">${words.length} ${T('kelime',words.length===1?'word':'words')}</p>${words.map(word=>`<button data-action="personal-select" data-item="${esc(word.id)}" aria-pressed="${word.id===selected.id}"><span lang="ja">${esc(word.written)}</span><small>${esc(word.meaning[state.settings.language])}</small></button>`).join('')}</aside><article class="personal-panel personal-word-detail"><div class="section-top"><span class="level-pill">${esc(p.decks.find(deck=>deck.id===selected.deckId)?.name||'')}</span><span class="personal-small">${selected.level==='unassigned'?T('Düzey belirtilmedi','Level unspecified'):esc(selected.level)}</span></div><h2 lang="ja">${kanjiText(selected.written,ui())}</h2><p class="personal-reading" lang="ja" ${p.showReading?'':'hidden'}>${esc(selected.reading)}</p><button class="reading-hint-button" data-action="personal-toggle-reading" aria-pressed="${p.showReading}">${p.showReading?T('Okunuşu gizle','Hide reading'):T('Okunuşu göster','Show reading')}</button><p class="personal-meaning">${esc(L(selected.meaning))}</p>${pronunciationControls(selected,ui())}${selected.englishFallback&&state.settings.language==='en'?`<p class="personal-small">No English meaning was provided; your Turkish note is shown.</p>`:''}${selected.tags.length?`<div class="personal-tags">${selected.tags.map(tag=>`<span>${esc(tag)}</span>`).join('')}</div>`:''}${selected.example?`<p class="personal-small">${T('Kendi örneğin','Your example')}</p><p class="personal-example" lang="ja">${esc(selected.example)}</p>`:''}${selected.notes?`<p class="personal-note">${esc(selected.notes)}</p>`:''}<div class="personal-actions"><button class="btn secondary" data-action="personal-save-review" data-item="${esc(selected.id)}">${T('Tekrara ekle','Save for review')}</button><button class="btn secondary" data-action="personal-edit" data-item="${esc(selected.id)}">${T('Düzenle','Edit')}</button><button class="subtle-link" data-action="personal-remove" data-item="${esc(selected.id)}">${T('Kaldır','Remove')}</button></div><p class="personal-small">${T('Kaldırmak geçmiş cevaplarını silmez. Kelimeyi aşağıdaki kaldırılanlar bölümünden geri alabilirsin.','Removing does not erase past answers. You can restore the word in the removed section below.')}</p></article></div>`:`<section class="personal-panel personal-empty"><span class="personal-empty-glyph" lang="ja" aria-hidden="true">語</span><h2>${!p.decks.length?T('İlk destenle başla.','Start with your first deck.'):p.search?T('Bu aramada kelime bulunamadı.','No words match this search.'):T('Bu desteye ilk kelimeni ekle.','Add your first word to this deck.')}</h2><p>${!p.decks.length?T('Yukarıdan bir deste adı oluştur. Sonra tek tek kelime ekleyebilir veya bir CSV dosyasını önizleyebilirsin.','Create a deck above. Then add words individually or preview a CSV file.'):p.search?T('Daha kısa bir kelime, başka bir etiket veya bütün destelerle yeniden dene.','Try a shorter word, another tag or all decks.'):T('Japonca yazımı, kana okunuşunu ve kendi anlam notunu kaydederek başla.','Start by saving a Japanese word, its kana reading and your own meaning note.')}</p>${p.decks.length?`<div class="personal-actions"><button class="btn primary" data-action="personal-new-word">+ ${p.search?T('Yeni kelime ekle','Add a new word'):T('İlk kelimeni ekle','Add your first word')}</button>${p.search?`<form data-form="personal-search"><input type="hidden" name="query" value=""><button class="btn secondary" type="submit">${T('Aramayı temizle','Clear search')}</button></form>`:''}</div>`:''}</section>`;
  return header+options+wordForm(p)+(words.length?study:'')+browse+importArea(p)+(removed.length?`<details class="personal-panel personal-removed" data-disclosure-key="personal-removed"><summary>${T('Kaldırılan kelimeler','Removed words')} · ${removed.length}</summary>${removed.map(word=>`<div><span lang="ja">${esc(word.written)}</span><span>${esc(word.meaning.tr)}</span><button class="subtle-link" data-action="personal-restore" data-item="${esc(word.id)}">${T('Geri al','Restore')}</button></div>`).join('')}</details>`:'');
 }
 async function click(target){
  const action=target.dataset.action;if(!action?.startsWith('personal-'))return false;if(isBusy()||importing)return true;error=null;
  const state=getState(),p=current(),{T}=ui();
  try{
   if(action==='personal-new-word'){editorOpen=true;editingId=null;wordDraft=null;await repaint();document.querySelector('[data-form="personal-word"] [name="written"]')?.focus();}
   else if(action==='personal-cancel-editor'){editorOpen=false;editingId=null;wordDraft=null;await repaint();}
   else if(action==='personal-rename-deck'){const deck=p.decks.find(d=>d.id===target.dataset.deckId);if(deck){deckEditingId=deck.id;deckDraft=deck.name;await repaint();document.querySelector('[data-form="personal-deck"] [name="name"]')?.focus();}}
   else if(action==='personal-cancel-deck'){deckEditingId=null;deckDraft='';await repaint();}
   else if(action==='personal-select'){const next=structuredClone(state);next.personal.selectedWordId=target.dataset.item;await commit(next);}
   else if(action==='personal-toggle-reading'){const next=structuredClone(state);next.personal.showReading=!p.showReading;await commit(next);}
   else if(action==='personal-edit'){const word=p.words.find(w=>w.id===target.dataset.item&&!w.deletedAt);if(word){editingId=word.id;wordDraft=null;editorOpen=true;await repaint();document.querySelector('[data-form="personal-word"] [name="written"]')?.focus();}}
   else if(action==='personal-remove'){if(await commit(removePersonalWord(state,target.dataset.item)))toast(T('Kelime kaldırıldı. Geçmiş cevaplar korundu; aşağıdan geri alabilirsin.','Word removed. Past answers are preserved; you can restore it below.'));}
   else if(action==='personal-restore'){if(await commit(restorePersonalWord(state,target.dataset.item)))toast(T('Kelime geri alındı.','Word restored.'));}
   else if(action==='personal-save-review'){if(await commit(savePersonalForReview(state,target.dataset.item)))toast(T('Anlam ve okunuş kartları eklendi; cevap veya başarı kaydı üretilmedi.','Meaning and reading cards saved; no answer or success was recorded.'));}
   else if(action==='personal-start'){const session=createPersonalSession(state);if(session){const next=structuredClone(state);next.personal.session=session;if(await commit(next)){startedAt=performance.now();onQuestionStart();document.querySelector('.personal-session .answer-input')?.focus();}}}
   else if(action==='personal-close-session'){const next=structuredClone(state);next.personal.session=null;await commit(next);}
   else if(action==='personal-next'){if(p.session?.phase==='exercise'&&p.session.feedback){const next=structuredClone(state),s=next.personal.session;s.index++;s.feedback=null;if(s.index>=s.ids.length)s.phase='done';if(await commit(next)){startedAt=performance.now();onQuestionStart();(document.querySelector('.personal-session .answer-input')||document.querySelector('.personal-session h2'))?.focus();}}}
   else if(action==='personal-csv-template')download(personalCSV(state,{template:true}),'yomu-ornek-kelimeler.csv');
   else if(action==='personal-export')download(personalCSV(state),'yomu-kisisel-kelimeler.csv');
   else if(action==='personal-import-cancel'){fileGeneration++;readingCSV=false;preview=null;await repaint();}
   else if(action==='personal-import-confirm'){
    if(readingCSV){toast(T('Dosyanın okunmasını bekle.','Wait for the file to finish loading.'));return true;}
    const text=document.querySelector('[data-form="personal-import-preview"] [name="csvText"]')?.value??csvText;
    if(text!==previewText){csvText=text;preview=null;throw new PersonalError('csv-changed');}
    if(!preview||preview.errors.length||!preview.rows.length)throw new PersonalError('csv-invalid');
    importing=true;const savedPreview=preview,next=applyPersonalImport(state,preview);preview=null;csvText='';previewText='';
    if(await commit(next)){toast(T(`${savedPreview.count} kelime eklendi.`,`${savedPreview.count} ${savedPreview.count===1?'word':'words'} added.`));}else{preview=savedPreview;csvText=text;previewText=text;}
   }
  }catch(issue){error=issue;await repaint();}finally{importing=false;}
  return true;
 }
 async function submit(form){
  const type=form.dataset.form;if(!type?.startsWith('personal-'))return false;if(isBusy()||importing)return true;
  error=null;const state=getState(),p=current(),data=new FormData(form),{T}=ui();
  try{
   if(type==='personal-deck'){deckDraft=String(data.get('name')||'');const id=String(data.get('id')||''),next=id?renamePersonalDeck(state,id,deckDraft):createPersonalDeck(state,deckDraft),previousName=deckDraft,previousId=deckEditingId;deckDraft='';deckEditingId=null;if(!await commit(next)){deckDraft=previousName;deckEditingId=previousId;}}
   else if(type==='personal-word'){wordDraft=Object.fromEntries(data);const next=upsertPersonalWord(state,wordDraft),previousDraft=wordDraft,previousId=editingId;wordDraft=null;editorOpen=false;editingId=null;if(await commit(next))toast(T('Kelimen kaydedildi.','Your word was saved.'));else{wordDraft=previousDraft;editingId=previousId;editorOpen=true;}}
   else if(type==='personal-search'){const next=structuredClone(state);next.personal.search=String(data.get('query')||'').trim().slice(0,100);await commit(next);}
   else if(type==='personal-import-preview'){if(readingCSV){toast(T('Dosyanın okunmasını bekle.','Wait for the file to finish loading.'));return true;}csvText=String(data.get('csvText')||'');importDeckId=String(data.get('importDeckId')||'all');preview=preparePersonalImport(csvText,state,{deckId:importDeckId});previewText=csvText;await repaint();}
   else if(type==='personal-answer'){
    const s=p.session;if(!s||s.phase!=='exercise'||s.feedback||form.dataset.sessionId!==s.id||form.dataset.questionId!==s.ids[s.index])return true;
    const answer=String(data.get('answer')||'').trim();if(!answer)return true;const q=s.questions?.[s.index]||getPersonalQuestion(s.ids[s.index],state);if(!q)return true;
    const id=crypto.randomUUID(),next=recordAnswer(state,q,answer,new Date(),id,Math.min(600000,Math.round(performance.now()-startedAt)),'personal');
    next.personal.session.feedback=id;next.personal.session.eventIds.push(id);next.events.at(-1).readingHintShown=!!state.settings.questionReadings||!!s.readingHintIds?.includes(q.id);next.events.at(-1).pronunciationHintRequested=!!s.pronunciationHintIds?.includes(q.id);
    if(await commit(next))document.querySelector('.personal-session .feedback')?.focus({preventScroll:true});
   }
  }catch(issue){error=issue;await repaint();}
  return true;
 }
 async function change(target){
  if(target.matches?.('[data-personal-file="csv"]')){
   if(isBusy()||importing){toast(ui().T('İşlem sürüyor; dosyayı yeniden seç.','An action is in progress; select the file again.'));return true;}
   const file=target.files?.[0];if(!file)return true;const generation=++fileGeneration;error=null;preview=null;readingCSV=true;await repaint();
   try{if(file.size>PERSONAL_LIMITS.csvBytes)throw new PersonalError('csv-size');const text=await file.text();if(generation===fileGeneration)csvText=text;}catch(issue){if(generation===fileGeneration)error=issue;}finally{if(generation===fileGeneration){readingCSV=false;await repaint();}}return true;
  }
  if(target.matches?.('[data-personal-csv="text"]')){fileGeneration++;readingCSV=false;csvText=target.value;if(csvText!==previewText)preview=null;return true;}
  if(!target.dataset.personal)return false;if(isBusy()||importing)return true;
  const next=structuredClone(getState());if(target.dataset.personal==='deck'){next.personal.selectedDeckId=target.value;next.personal.selectedWordId='';}else if(target.dataset.personal==='mode')next.personal.mode=target.value;
  await commit(next);return true;
 }
 return{page,click,submit,change};
}
